scripts:
local down_Time = 30
repeat wait() until script.Parent:WaitForChild'Player_Name'.Value ~= ' ';print'Not " " ';
local s = script;
local sp = s.Parent;
local name = sp.Player_Name.Value;
local plrs = game.Players;
local plr = plrs:FindFirstChild(name);
local part = sp.Parent;
local remove = function(x)x:Destroy()end;
local Table_Search = function(tab,str)
	local x = false;
	for i = 1,#tab do
		if tab[i] == str then
			x=str;
		end;
	end;
	return x;
end;
local Table_PosSearch = function(tab,str)
	local x = false;
	for i = 1,#tab do
		if tab[i] == str then
			x=i;
		end
	end
	return x;
end;
sp.TextLabel.Text='Revive ' .. name .. ' [ ' .. down_Time .. ' ]';
coroutine.resume(coroutine.create(function()
	for i = down_Time,0,-1 do
		sp.TextLabel.Text='Revive ' .. name .. ' [ ' .. i .. ' ]';wait(1);
	end;
	if workspace:findFirstChild(name)and workspace[name]:findFirstChild'Humanoid' then
		workspace[name].Humanoid.Health=0
	end
	script.Parent.Parent.Parent:Destroy()
end));
local debounce = {};
sp.Parent.Touched:connect(function(hit)
	local char = hit.Parent
	local plrHit = plrs:findFirstChild(char.Name)
	if plrHit and char:findFirstChild'Humanoid' and Table_Search(debounce,plrHit.Name) == false
	and plrHit:WaitForChild'PlayerGui':findFirstChild'Revive'==nil and plrHit.Name ~= name then
		table.insert(debounce,plrHit.Name)
		local hum = char['Humanoid']
		if hum.Health > 0 then
			local r = script.Parent.Revive:Clone();r.Player_Name.Value = name
			r.Parent = plrHit:WaitForChild'PlayerGui'
			while wait() do if workspace:findFirstChild(plrHit.Name)and workspace[plrHit.Name]:findFirstChild'Torso' then
				if (workspace[plrHit.Name]['Torso'].Position - sp.Parent.Position).magnitude > 10 then
					if plrs:findFirstChild(plrHit.Name) and plrs[plrHit.Name]:WaitForChild'PlayerGui':findFirstChild'Revive' then
						local pos = Table_PosSearch(debounce,plrHit.Name)
						if pos ~= false then
							table.remove(debounce,pos)
						end
						remove(plrs[plrHit.Name].PlayerGui['Revive'])
						break
					else
						local pos = Table_PosSearch(debounce,plrHit.Name)
						if pos ~= false then
							table.remove(debounce,pos)
						end
					end
				end
			end
			end
		end
	end
end)
